import{_ as r,l as t,o as e,c as i,v as s,p as l,x as n,d,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"离岸外包与任务","description":"","frontmatter":{"title":"离岸外包与任务","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/offshoring-tasks.md","filePath":"econ/offshoring-tasks.md","lastUpdated":1789023840000}'),B={name:"econ/offshoring-tasks.md"};function A(h,a,c,_,m,f){const o=t("Mermaid");return e(),i("div",null,[a[1]||(a[1]=s('<h1 id="离岸外包与任务" tabindex="-1">离岸外包与任务 <a class="header-anchor" href="#离岸外包与任务" aria-label="Permalink to &quot;离岸外包与任务&quot;">​</a></h1><div class="epigraph"><p>可贸易的不是行业而是任务；离岸像劳动增进型技术进步，可以同时提高生产率与改变技能溢价——符号取决于哪些任务被切开。</p><footer>—— Grossman and Rossi-Hansberg, Trading Tasks, AER 2008；Feenstra and Hanson 外包与工资</footer></div><p><a href="/econ/china-shock">上一课</a>用行业暴露度量进口竞争。本课缺口是：同一行业内，一部分任务去了国外，一部分留下，工资效应不必等于「整个行业被进口替代」。贸易与增长下一课换长期；本课钉任务贸易。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Feenstra–Hanson：把生产切片，把低技能密集的中间阶段离岸，相当于发达国家低技能劳动的有效供给增加，扩大工资差距。Grossman–Rossi-Hansberg（GRH）：任务连续统，离岸成本随任务下降，像对离岸任务的技术进步；对留下的同类劳动有生产率效应（正）与替代效应（负），相对工资符号不定。缺口不是再跑一条 CZ 回归，而是：暴露应从任务 / 职业可离岸性来，而不仅从行业进口渗透。</p><p><span class="marginnote">Blinder 的职业离岸清单、Autor 的例行任务，是劳动侧分类。贸易侧 GRH 给一般均衡价格。两边合在一起才不会把「电脑」与「中国」混成一个残差。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把最终品生产写成任务积分，每个任务可用本国或外国劳动。冰山或固定协调成本决定截止任务。比较静态：协调成本下降，截止点外移，本国任务集中到更核心的。工资：生产率效应对所有执行留下任务的人；相对价格效应改技能溢价。计量：职业暴露（可离岸指数）对工资，控制行业；与 ADH 行业暴露对照，看是否独立。</p>',8)),(e(),l(p,null,{default:n(()=>[E(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TASK%5B%22%E4%BB%BB%E5%8A%A1%E8%BF%9E%E7%BB%AD%E7%BB%9F%22%5D%20--%3E%20CUT%5B%22%E7%A6%BB%E5%B2%B8%E6%88%AA%E6%AD%A2%22%5D%0A%20%20COST%5B%22%E5%8D%8F%E8%B0%83%E6%88%90%E6%9C%AC%E4%B8%8B%E9%99%8D%22%5D%20--%3E%20CUT%0A%20%20CUT%20--%3E%20PROD%5B%22%E7%94%9F%E4%BA%A7%E7%8E%87%E6%95%88%E5%BA%94%20%2B%22%5D%0A%20%20CUT%20--%3E%20SUB%5B%22%E6%9B%BF%E4%BB%A3%E6%95%88%E5%BA%94%20%E2%88%92%22%5D%0A%20%20NET%5B%22%E7%9B%B8%E5%AF%B9%E5%B7%A5%E8%B5%84%E7%AC%A6%E5%8F%B7%E4%B8%8D%E5%AE%9A%22%5D%0A%20%20PROD%20--%3E%20NET%0A%20%20SUB%20--%3E%20NET%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=s('<p>与 GVC 会计：任务是理论对象，增加值是账户对象。离岸使总额贸易升得比 VA 更快（往返运输）。与 Melitz：企业选择离岸哪些任务，高 \\(\\varphi\\) 企业更可能组织复杂链。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是成本下降使切片变细，而不是「一个行业消失」。留下的工人与外国任务互补（用进口中间品），其边际产出可升——这是 ADH 对照组里出口与下游企业受益的通道。替代效应是直接抢任务。政策把两者加总进一个「进口渗透」里，会把互补当冲击。</p><p>与 SS：SS 是商品价格 → 要素价格。任务贸易可以在商品相对价格变化不大时改变要素价格（有效技术变了）。这是 Feenstra 强调外包可以解释工资差距而最终品价格变动不够大的理由。</p><p><span class="marginnote">不要把离岸写成只有制造业。可编码的服务任务同样走 GRH。本课不写远程软件的企业名录。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不仲裁「中国 vs 机器人」的方差分解。不把 GRH 符号写成永远正或永远负。贸易–增长课问的是动态创新，不是任务切片的一次性。不要用任务取消行业暴露：两者是不同投影，ADH 仍然有效，只是机制要加一层。</p><p>后课默认：贸易对象可以是任务；离岸有生产率与替代两效应，工资符号不是 SS 的简单复制。行业进口渗透会把下游互补算进冲击，解释时要拆。价值链会计与任务理论对接，但不互相替代。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可离岸的是任务，不是整个行业标签。</li><li>Feenstra–Hanson：离岸低技能阶段扩大技能溢价。</li><li>GRH：生产率效应与替代效应对冲，符号不定。</li><li>度量应从职业 / 任务暴露补行业渗透。</li><li>出处：Grossman and Rossi-Hansberg, <em>AER</em> 2008；Feenstra and Hanson。</li></ul>',10))])}const D=r(B,[["render",A]]);export{u as __pageData,D as default};
